    def find_root():
        children = set(leftChild + rightChild)
        for i in range(n):
            if i not in children:
                return i
        return -1

    # Helper function to perform DFS and check for cycles
    def dfs(node, visited, parent):
        if node == -1:
            return True
        if node in visited:
            return False
        visited.add(node)
        if not dfs(leftChild[node], visited, node):
            return False
        if not dfs(rightChild[node], visited, node):
            return False
        return True

